def crear_documentos() -> None:
    """Crea los documentos del reglamento en DATA_DIR, solo los que todavía no existen."""
    config.DATA_DIR.mkdir(parents=True, exist_ok=True)
    for nombre, contenido in documentos.items():
        ruta = config.DATA_DIR / nombre
        if ruta.exists():
            logger.info("Archivo %s ya existe, se omite.", nombre)
            continue
        ruta.write_text(contenido.strip(), encoding="utf-8")
        logger.info("Archivo %s creado con éxito.", nombre)


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")
    crear_documentos()
